"""Blackjack with Monte Carlo: prediction for a fixed policy and on-policy epsilon-soft control.

Cards are drawn with replacement; dealer hits below 17. State = (player sum 12-21, dealer showing 1-10, usable ace).
Reward +1 win, 0 draw, -1 loss; gamma = 1, so the return is the final reward.
"""
import random
random.seed(1)
def card(): return min(random.randint(1, 13), 10)
def total(cards):
    s = sum(cards); ace = 1 in cards and s + 10 <= 21
    return (s + 10 if ace else s), ace
def episode(policy, start_state=None, start_action=None):
    player, dealer = [card(), card()], [card(), card()]
    while total(player)[0] < 12: player.append(card())
    traj, first = [], True
    while True:
        s = (total(player)[0], dealer[0], total(player)[1])
        a = start_action if (first and start_action is not None) else policy(s); first = False
        traj.append((s, a))
        if a == 1:                                   # hit
            player.append(card())
            if total(player)[0] > 21: return traj, -1
        else: break
    while total(dealer)[0] < 17: dealer.append(card())
    p, d = total(player)[0], total(dealer)[0]
    return traj, (1 if d > 21 or p > d else 0 if p == d else -1)

# 1) prediction: stick only on 20 or 21
V, N = {}, {}
stick20 = lambda s: 0 if s[0] >= 20 else 1
for _ in range(200_000):
    traj, G = episode(stick20)
    for s in {s for s, a in traj}:                   # each state at most once per episode here
        N[s] = N.get(s, 0) + 1; V[s] = V.get(s, 0) + (G - V.get(s, 0)) / N[s]
print("V under 'stick on 20+' (no usable ace), dealer shows 10:")
print("  " + "  ".join(f"{p}:{V[(p, 10, False)]:+.2f}" for p in range(12, 22)))

# 2) on-policy first-visit MC control with an epsilon-soft policy
Q, C = {}, {}
eps = 0.1
def greedy(s): return max((0, 1), key=lambda a: Q.get((s, a), 0.0))
def soft(s): return random.randint(0, 1) if random.random() < eps else greedy(s)
for _ in range(400_000):
    traj, G = episode(soft)
    for s, a in set(traj):
        C[(s, a)] = C.get((s, a), 0) + 1; Q[(s, a)] = Q.get((s, a), 0) + (G - Q.get((s, a), 0)) / C[(s, a)]
print("\nLearned greedy policy, no usable ace (H = hit, S = stick); rows = player sum, cols = dealer 1..10")
for p in range(21, 11, -1):
    print(f"  {p}: " + " ".join("S" if greedy((p, d, False)) == 0 else "H" for d in range(1, 11)))
